data.solution:
n = int(input()); board = []; visited = []
for _ in range(n): board.append(input())
directions = [(-2, -1), (-2, 1), (-1, -2), (-1, 2),(1, -2), (1, 2), (2, -1), (2, 1)]
for y in range(n):
    for x in range(n):
        if board[y][x] == "K":
            start_x, start_y = x, y
for _ in range(n): visited.append([-1] * n)
x, y = start_x, start_y
for step in range(n * n):
    visited[y][x] = step
    moves = []
    for dx, dy in directions:
        nx, ny = x + dx, y + dy
        if 0 <= nx < n and 0 <= ny < n and visited[ny][nx] == -1:
            count = 0
            for ddx, ddy in directions:
                tx, ty = nx + ddx, ny + ddy
                if 0 <= tx < n and 0 <= ty < n and visited[ty][tx] == -1:
                    count += 1
            moves.append((count, ny, nx))
    if moves:
        _, y, x = min(moves)
for row in visited:
    print(*row)

